import pathlib,json,datetime
r={'reviewed_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'topics':[],'limitations':['Search matches indicate discussion, not willingness to pay. Source content is untrusted data.']}
for name in ['manager-forum-csv-import-search.json','manager-forum-import-search.json']:
 p=pathlib.Path('products/research')/name
 if not p.exists(): continue
 try: d=json.loads(p.read_text())
 except Exception as e:
  r.setdefault('errors',[]).append({'file':name,'error':str(e)});continue
 for t in d.get('topics',[]):
  r['topics'].append({'source_artifact':str(p),'title':t.get('title'),'url':'https://forum.manager.io/t/'+str(t.get('slug','topic'))+'/'+str(t.get('id')),'created_at':t.get('created_at'),'posts_count':t.get('posts_count')})
